css:
:scope { width: min(100%, 1200px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 7 / span 11; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 14px; font-weight: 500; line-height: 1.5; letter-spacing: 0.39em; text-transform: uppercase; color: inherit; }
.gx__i2 { grid-column: 4 / span 18; grid-row: 7 / span 8; font-family: var(--os-font-heading); font-size: 61px; font-weight: 400; line-height: 1; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i3 { grid-column: 7 / span 12; grid-row: 20 / span 19; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.47; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__p4 { grid-column: 1 / span 8; grid-row: 45 / span 23; background: var(--os-color-background);  border-radius: 20px; }
.gx__p5 { grid-column: 9 / span 8; grid-row: 45 / span 23; background: var(--os-color-background);  border-radius: 20px; }
.gx__p6 { grid-column: 17 / span 8; grid-row: 45 / span 23; background: var(--os-color-background);  border-radius: 20px; }
.gx__i7 { grid-column: 1 / span 7; grid-row: 52 / span 3; font-family: var(--os-font-heading); font-size: 19px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i8 { grid-column: 9 / span 7; grid-row: 52 / span 3; font-family: var(--os-font-heading); font-size: 19px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i9 { grid-column: 17 / span 7; grid-row: 52 / span 3; font-family: var(--os-font-heading); font-size: 19px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i10 { grid-column: 1 / span 7; grid-row: 57 / span 8; font-family: var(--os-font-heading); font-size: 16px; font-weight: 400; line-height: 1.31; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i11 { grid-column: 9 / span 7; grid-row: 57 / span 8; font-family: var(--os-font-heading); font-size: 16px; font-weight: 400; line-height: 1.31; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i12 { grid-column: 17 / span 7; grid-row: 57 / span 8; font-family: var(--os-font-heading); font-size: 16px; font-weight: 400; line-height: 1.31; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i13 { grid-column: 11 / span 4; grid-row: 77 / span 6; font-family: var(--os-font-body); font-size: 12px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-transform: uppercase; text-align: center; color: var(--os-color-background); }
.gx__i13 { justify-self: center; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 49px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__p4 { display: none; }
  .gx__p5 { display: none; }
  .gx__p6 { display: none; }
  .gx__i7 { font-family: var(--os-font-heading); font-size: 15px; }
  .gx__i8 { font-family: var(--os-font-heading); font-size: 15px; }
  .gx__i9 { font-family: var(--os-font-heading); font-size: 15px; }
  .gx__i10 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i13 { font-family: var(--os-font-body); font-size: 14px; }
}
